import{useEffect,useState}from'react';import type{RouteConfig}from'@mercurjs/dashboard-sdk';import{Actions,Button,Card,Empty,Message,Page,PageHeader,Status}from'../../spike/ui';import{Table,TableBody,TableCell,TableHead,TableHeader,TableRow}from'../../components/ui/table';declare const __BACKEND_URL__:string;export const config:RouteConfig={label:'المرتجعات',rank:68};const api=async(p:string,i?:RequestInit)=>{const r=await fetch(`${__BACKEND_URL__}${p}`,{credentials:'include',...i,headers:{...(i?.body?{'content-type':'application/json'}:{}),...(i?.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||`HTTP ${r.status}`);return d};const tone=(s:string):any=>s==='approved'?'success':s==='rejected'?'danger':s==='requested'?'warning':'muted';const label=(s:string)=>s==='requested'?'بانتظار المراجعة':s==='approved'?'مقبول':s==='rejected'?'مرفوض':s||'—';export default function P(){const[x,setX]=useState<any[]>([]),[m,setM]=useState(''),[busy,setBusy]=useState('');const load=()=>api('/vendor/spike/returns').then(d=>setX(d.returns||[]));useEffect(()=>{load().catch(e=>setM(e.message))},[]);const act=async(id:string,a:string)=>{let reason='';if(a==='reject'&&!(reason=prompt('سبب الرفض')||''))return;try{setBusy(id);await api(`/vendor/spike/returns/${id}`,{method:'POST',body:JSON.stringify({action:a,reason})});setM(a==='approve'?'تم قبول المرتجع وإضافة مبلغ العميل للمستحقات':'تم رفض المرتجع');await load()}catch(e:any){setM(e.message)}finally{setBusy('')}};return <Page><PageHeader title="المرتجعات" description="راجع طلبات الإرجاع الخاصة بمنتجات متجرك وحدد النتيجة بعد فحص المنتج."/>{m&&<Message>{m}</Message>}<Card>{x.length?<Table><TableHeader><TableRow><TableHead>الطلب</TableHead><TableHead>المنتج</TableHead><TableHead>المبلغ</TableHead><TableHead>الحالة</TableHead><TableHead>الإجراء</TableHead></TableRow></TableHeader><TableBody>{x.map(r=><TableRow key={r.id}><TableCell>#{r.order_id}</TableCell><TableCell>{r.product_title||r.product_id}</TableCell><TableCell>{r.amount} {r.currency_code}</TableCell><TableCell><Status tone={tone(r.status)}>{label(r.status)}</Status></TableCell><TableCell>{r.status==='requested'?<Actions><Button disabled={busy===r.id} onClick={()=>act(r.id,'approve')}>قبول - رجع سليم</Button><Button tone="danger" disabled={busy===r.id} onClick={()=>act(r.id,'reject')}>رفض</Button></Actions>:<span className="text-muted-foreground">تمت المراجعة</span>}</TableCell></TableRow>)}</TableBody></Table>:<Empty>لا توجد طلبات إرجاع حاليًا.</Empty>}</Card></Page>}
